arguments.command:
curl -s http://web:80/ -H "Host: localhost" -u admin:admin -o /dev/null -w "Host localhost: %{http_code}
"; curl -s -u admin:admin http://127.0.0.1:80/ -o /dev/null -w "IP: %{http_code}
"; curl -s -u admin:admin http://web:80/ -H "User-Agent:" -o /dev/null -w "no UA: %{http_code}
"; curl -s -u admin:admin http://web:80/ -H "Accept: */*" -o /dev/null -w "accept: %{http_code}
"

echo "no auth:"; curl -s -o /dev/null -w "%{http_code}
" http://web:80/
echo "basic empty (":"):"; curl -s -o /dev/null -w "%{http_code}
" -H "Authorization: Basic Og==" http://web:80/
echo "basic admin:admin:"; curl -s -o /dev/null -w "%{http_code}
" -H "Authorization: Basic YWRtaW46YWRtaW4=" http://web:80/
echo "garbage base64:"; curl -s -o /dev/null -w "%{http_code}
" -H "Authorization: Basic xyz" http://web:80/
echo "bearer:"; curl -s -o /dev/null -w "%{http_code}
" -H "Authorization: Bearer abc" http://web:80/
echo "authorization blank:"; curl -s -o /dev/null -w "%{http_code}
" -H "Authorization:" http://web:80/
echo "single colon:"; curl -s -o /dev/null -w "%{http_code}
" -H "Authorization: Basic Og==" http://web:80/x; echo "http1.0:"; curl -s --http1.0 -o /dev/null -w "%{http_code}
" -u admin:admin http://web:80/

echo "server-status auth:"; curl -s -i -u admin:admin http://web:80/server-status | head -8
echo "server-info auth:"; curl -s -i -u admin:admin http://web:80/server-info | head -8
echo "icons:"; curl -s -o /dev/null -w "noauth: %{http_code}
" http://web:80/icons/; curl -s -o /dev/null -w "auth: %{http_code}
" -u admin:admin http://web:80/icons/
echo "manual:"; curl -s -o /dev/null -w "noauth: %{http_code}
" http://web:80/manual/; curl -s -o /dev/null -w "auth: %{http_code}
" -u admin:admin http://web:80/manual/
echo "error dir:"; curl -s -o /dev/null -w "noauth: %{http_code}
" http://web:80/error/; curl -s -o /dev/null -w "auth: %{http_code}
" -u admin:admin http://web:80/error/
